use std::env;
use std::fs;
use std::process;

const MALFORMED_ROW: &str = "what=malformed TSV row; why=expected exactly two tab-separated fields; fix=write <key><tab><value>";
const EMPTY_KEY: &str = "what=empty TSV key; why=each row needs a named report field; fix=write name, count, or note before the tab";
const UNKNOWN_KEY: &str = "what=unknown TSV key; why=only name, count, and note are valid report fields; fix=use one of the required keys";
const DUPLICATE_KEY: &str = "what=duplicate TSV key; why=each report field must appear once; fix=remove the repeated row";
const INVALID_COUNT: &str = "what=invalid count value; why=count must be a decimal integer; fix=write a whole-number count";
const MISSING_KEY: &str = "what=missing required TSV key; why=report needs name, count, and note; fix=add the missing row";

fn fail(path: &str, line: usize, reason: &str) -> ! {
    eprintln!("{path}:{line}:{reason}");
    process::exit(1);
}

fn json_escape(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            character if (character as u32) < 0x20 => {
                escaped.push_str(&format!("\\u{:04x}", character as u32));
            }
            character => escaped.push(character),
        }
    }
    escaped
}

fn main() {
    let mut arguments = env::args();
    let _program = arguments.next();
    let path = arguments.next().unwrap_or_else(|| {
        eprintln!("missing report path");
        process::exit(1);
    });
    let source = fs::read_to_string(&path).unwrap_or_else(|error| {
        eprintln!("read failed: {error}");
        process::exit(1);
    });

    let mut name = String::new();
    let mut count_text = String::new();
    let mut note = String::new();
    let mut count_line = 0usize;
    let mut seen_name = false;
    let mut seen_count = false;
    let mut seen_note = false;
    let mut line_number = 0usize;

    for line in source.lines() {
        line_number += 1;
        let parts: Vec<&str> = line.splitn(3, '\t').collect();
        if parts.len() != 2 {
            fail(&path, line_number, MALFORMED_ROW);
        }
        let key = parts[0].trim();
        let value = parts[1];
        if key.is_empty() {
            fail(&path, line_number, EMPTY_KEY);
        }
        match key {
            "name" => {
                if seen_name {
                    fail(&path, line_number, DUPLICATE_KEY);
                }
                name = value.to_string();
                seen_name = true;
            }
            "count" => {
                if seen_count {
                    fail(&path, line_number, DUPLICATE_KEY);
                }
                count_text = value.to_string();
                count_line = line_number;
                seen_count = true;
            }
            "note" => {
                if seen_note {
                    fail(&path, line_number, DUPLICATE_KEY);
                }
                note = value.to_string();
                seen_note = true;
            }
            _ => fail(&path, line_number, UNKNOWN_KEY),
        }
    }

    if !seen_name || !seen_count || !seen_note {
        fail(&path, line_number + 1, MISSING_KEY);
    }
    let count: i64 = count_text.parse().unwrap_or_else(|_| fail(&path, count_line, INVALID_COUNT));
    println!(
        "{{\"count\":{},\"name\":\"{}\",\"note\":\"{}\"}}",
        count,
        json_escape(&name),
        json_escape(&note)
    );
}
